SourceCode.Declaration:
/// <summary>
/// Request for one purchase order, as the handheld's PO step needs it.
///
/// The warehouse is carried but not used to filter the order: an operator who scans a PO that
/// belongs to another warehouse must be told so by name, not shown an empty line list. The
/// service echoes the order's own warehouse back and lets the client decide.
/// </summary>
[DataContractAttribute]
class HSMobileOpsPurchOrderRequest
{
    DataAreaId          dataAreaId;
    PurchId             purchId;
    InventLocationId    warehouseId;

}

Method.Source:
/// <summary>
/// Legal entity to read in.
///
/// Mandatory, and never defaulted to the service account's company. The mobile app
/// authenticates as a service principal whose default company is an accident of setup;
/// silently reading the wrong legal entity is the failure this field exists to prevent.
/// </summary>
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('PurchId')]
public PurchId parmPurchId(PurchId _value = purchId)
{
    purchId = _value;
    return purchId;
}

[DataMemberAttribute('WarehouseId')]
public InventLocationId parmWarehouseId(InventLocationId _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}
